#include <bits/stdc++.h>
using namespace std;

using vi = vector<int>;
using vvi = vector<vi>;
using pii = pair<int, int>;
using ll = long long;
using ld = long double;

const int MAXN = 1e5 + 10;
const int MOD = 1e9 + 7;
const ll INF = 1e18;

// Fast input/output
inline int ni() { int x; scanf("%d", &x); return x; }
inline string ns() { char buf[1001000]; scanf("%s", buf); return string(buf); }

struct Edge {
    int src, dst, cap, flow;
};

struct Dinic {
    int N;
    vector<Edge> edges;
    vector<vector<int>> adj;
    vi level, ptr;

    Dinic(int n = 0) : N(n), adj(n), level(n), ptr(n) {}

    void addEdge(int s, int d, int c) {
        edges.push_back({s, d, c, 0});
        edges.push_back({d, s, 0, 0});
        adj[s].push_back(edges.size() - 2);
        adj[d].push_back(edges.size() - 1);
    }

    bool bfs(int s, int t) {
        fill(level.begin(), level.end(), -1);
        queue<int> q;
        q.push(s);
        level[s] = 0;
        while (!q.empty() && level[t] == -1) {
            int u = q.front(); q.pop();
            for (int idx : adj[u]) {
                auto &e = edges[idx];
                if (level[e.dst] == -1 && e.flow < e.cap) {
                    level[e.dst] = level[u] + 1;
                    q.push(e.dst);
                }
            }
        }
        return level[t] != -1;
    }

    int dfs(int u, int flow, int t) {
        if (!flow || u == t) return flow;
        for (int &i = ptr[u]; i < (int)adj[u].size(); ++i) {
            int idx = adj[u][i];
            auto &e = edges[idx];
            if (level[e.dst] != level[u] + 1) continue;
            int pushed = dfs(e.dst, min(flow, e.cap - e.flow), t);
            if (pushed) {
                e.flow += pushed;
                edges[idx ^ 1].flow -= pushed;
                return pushed;
            }
        }
        return 0;
    }

    int maxFlow(int s, int t) {
        int flow = 0;
        while (bfs(s, t)) {
            fill(ptr.begin(), ptr.end(), 0);
            while (int pushed = dfs(s, (int)INF, t))
                flow += pushed;
        }
        return flow;
    }
};

int n, t;
string a[30], b[30];
int dist1[30][30], dist2[30][30];
int dx[4] = {0, 0, -1, 1};
int dy[4] = {1, -1, 0, 0};

inline bool in_bounds(int x, int y) {
    return x >= 0 && x < n && y >= 0 && y < n;
}

void bfs1(int sx, int sy) {
    for (int i = 0; i < 30; ++i)
        for (int j = 0; j < 30; ++j)
            dist1[i][j] = 1e9;
    queue<pii> q;
    q.push({sx, sy});
    dist1[sx][sy] = 0;
    while (!q.empty()) {
        auto [x, y] = q.front(); q.pop();
        for (int d = 0; d < 4; ++d) {
            int nx = x + dx[d], ny = y + dy[d];
            if (in_bounds(nx, ny) && dist1[nx][ny] == 1e9 && b[nx][ny] != 'Y') {
                dist1[nx][ny] = dist1[x][y] + 1;
                q.push({nx, ny});
            }
        }
    }
}

void bfs2(int sx, int sy) {
    for (int i = 0; i < 30; ++i)
        for (int j = 0; j < 30; ++j)
            dist2[i][j] = 1e9;
    queue<pii> q;
    q.push({sx, sy});
    dist2[sx][sy] = 0;
    while (!q.empty()) {
        auto [x, y] = q.front(); q.pop();
        if (dist2[x][y] >= dist1[x][y]) continue;
        for (int d = 0; d < 4; ++d) {
            int nx = x + dx[d], ny = y + dy[d];
            if (in_bounds(nx, ny) && dist2[nx][ny] == 1e9 && a[nx][ny] != 'Y' && dist2[x][y] + 1 <= dist1[nx][ny]) {
                dist2[nx][ny] = dist2[x][y] + 1;
                q.push({nx, ny});
            }
        }
    }
}

int main() {
    n = ni(); t = ni();
    for (int i = 0; i < n; ++i) a[i] = ns();
    for (int i = 0; i < n; ++i) {
        b[i] = ns();
        for (int j = 0; j < n; ++j) {
            if (b[i][j] == 'Z') {
                b[i][j] = a[i][j] = 'Y';
                swap(i, n); // mark to exit inner loop
                break;
            }
        }
    }

    int zx = -1, zy = -1;
    for (int i = 0; i < n; ++i)
        for (int j = 0; j < n; ++j)
            if (b[i][j] == 'Y' && a[i][j] == 'Y') {
                zx = i; zy = j;
                break;
            }

    bfs1(zx, zy);

    Dinic din(n * n * 2 + 5);
    int src = 0, dst = 2 * n * n + 1;

    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            if (a[i][j] == 'Y') continue;
            int u = i * n + j + 1;
            int v = n * n + u;
            din.addEdge(src, u, a[i][j] - '0');
            din.addEdge(v, dst, b[i][j] - '0');
            bfs2(i, j);
            for (int x = 0; x < n; ++x) {
                for (int y = 0; y < n; ++y) {
                    if (b[x][y] == 'Y' || dist2[x][y] > t) continue;
                    din.addEdge(u, n * n + x * n + y + 1, a[i][j] - '0');
                }
            }
        }
    }

    printf("%d\n", din.maxFlow(src, dst));
}
